Aşağıdaki Python 3.14 kodu çalıştırılınca ekrana tam olarak ne yazdırılır? Kodu kafanda adım adım çalıştır. Cevabının sonunda çıktıyı birebir (her satır ayrı) tek bir ```text bloğu içinde ver.

```python
import functools

kayit = []


def izle(etiket):
    def dekorator(f):
        kayit.append(f"tanim:{etiket}:{f.__name__}")

        @functools.wraps(f)
        def sarmal(*a, **k):
            kayit.append(f"cagri:{etiket}")
            return f(*a, **k) + 1
        return sarmal
    return dekorator


@izle("dis")
@izle("ic")
def topla(x, y=10):
    return x + y


print(topla(1), topla.__name__)
print(kayit)


def ekle(x, liste=[]):
    liste.append(x)
    return len(liste)


print(ekle(1), ekle(2), ekle(3, []), ekle(4))
carpanlar = {k: (lambda v: v * k) for k in range(3)}
print([f(10) for f in carpanlar.values()])
print({**{"a": 1, "b": 2}, **{"b": 3}, "a": 0})
```
